def transform(grid):
    g=[row[:] for row in grid]; m=len(g); n=len(g[0])
    # identify the two exterior edges occupied by the frame color
    from collections import Counter
    colors=Counter(x for row in g for x in row)
    # one color forms exactly two full outer edges
    frame=None
    for color in colors:
        edges=[all(x==color for x in g[0]),all(x==color for x in g[-1]),all(row[0]==color for row in g),all(row[-1]==color for row in g)]
        if sum(edges)==2: frame=color; break
    bg=next(c for c in colors if c!=frame)
    out=[[8]*n for _ in range(m)]
    top=all(x==frame for x in g[0]); bottom=all(x==frame for x in g[-1]); left=all(row[0]==frame for row in g); right=all(row[-1]==frame for row in g)
    # Retain background along the original frame edges except their shared corner.
    for r in range(m):
        for c in range(n):
            if ((r==0 and top) or (r==m-1 and bottom) or (c==0 and left) or (c==n-1 and right)):
                out[r][c]=bg
    # Move each frame edge one cell inward.
    if top:
        for c in range(n): out[1][c]=frame
    if bottom:
        for c in range(n): out[m-2][c]=frame
    if left:
        for r in range(m): out[r][1]=frame
    if right:
        for r in range(m): out[r][n-2]=frame
    # Background diagonal immediately inward from the shifted frame.
    if top and left:
        for k in range(2,min(m,n)): out[k][k]=bg
        out[0][0]=8
    elif top and right:
        for k in range(2,min(m,n)): out[k][n-1-k]=bg
        out[0][n-1]=8
    elif bottom and left:
        for k in range(2,min(m,n)): out[m-1-k][k]=bg
        out[m-1][0]=8
    elif bottom and right:
        for k in range(2,min(m,n)): out[m-1-k][n-1-k]=bg
        out[m-1][n-1]=8
    return out
